// Main component
const BedtimeMode = ({ settings, updateSettings, currentStory }) => {
  const navigate = useNavigate();
  const [isBedtimeEnabled, setIsBedtimeEnabled] = useState(false);
  const [fadeDuration, setFadeDuration] = useState(settings.bedtimeFadeDuration || 15);
  const [remainingTime, setRemainingTime] = useState(0);
  const [volume, setVolume] = useState(1);
  const [selectedLullaby, setSelectedLullaby] = useState('lullaby');

  // References for animations and sounds
  const timerRef = useRef(null);
  const fadeIntervalRef = useRef(null);
  const lullabySound = useRef(null);

  // Initialize lullaby sounds
  useEffect(() => {
    // Clean up on unmount
    return () => {
      if (lullabySound.current) {
        lullabySound.current.stop();
      }

      if (timerRef.current) {
        clearInterval(timerRef.current);
      }

      if (fadeIntervalRef.current) {
        clearInterval(fadeIntervalRef.current);
      }
    };
  }, []);

  // Toggle bedtime mode
  const toggleBedtimeMode = async () => {
    try {
      if (!isBedtimeEnabled) {
        // Enable bedtime mode
        const result = await enableBedtimeMode(fadeDuration);

        if (result.success) {
          setIsBedtimeEnabled(true);
          startBedtimeMode();
        }
      } else {
        // Disable bedtime mode
        const result = await disableBedtimeMode();

        if (result.success) {
          setIsBedtimeEnabled(false);
          stopBedtimeMode();
        }
      }
    } catch (error) {
      console.error('Error toggling bedtime mode:', error);
    }
  };

  // Start bedtime mode
  const startBedtimeMode = () => {
    // Set initial values
    const totalSeconds = fadeDuration * 60;
    setRemainingTime(totalSeconds);
    setVolume(1);

    // Start countdown timer
    timerRef.current = setInterval(() => {
      setRemainingTime(prev => {
        if (prev <= 1) {
          clearInterval(timerRef.current);
          playLullaby();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    // Start volume fade
    const fadeStepTime = 1000; // Update volume every second
    const fadeStep = 1 / (totalSeconds); // Volume reduction per step

    fadeIntervalRef.current = setInterval(() => {
      setVolume(prev => {
        const newVolume = Math.max(0, prev - fadeStep);

        // If volume reaches 0, clear the interval
        if (newVolume <= 0) {
          clearInterval(fadeIntervalRef.current);
        }

        return newVolume;
      });
    }, fadeStepTime);
  };

  // Stop bedtime mode
  const stopBedtimeMode = () => {
    // Clear timers
    if (timerRef.current) {
      clearInterval(timerRef.current);
    }

    if (fadeIntervalRef.current) {
      clearInterval(fadeIntervalRef.current);
    }

    // Stop lullaby if playing
    if (lullabySound.current) {
      lullabySound.current.stop();
    }

    // Reset values
    setRemainingTime(0);
    setVolume(1);
  };

  // Play selected lullaby
  const playLullaby = () => {
    // Stop any currently playing lullaby
    if (lullabySound.current) {
      lullabySound.current.stop();
    }

    // Get the sound URL based on selection
    let soundUrl;
    switch (selectedLullaby) {
      case 'lullaby':
        soundUrl = soundEffects.lullaby;
        break;
      case 'white_noise':
        soundUrl = soundEffects.white_noise;
        break;
      case 'silence':
      default:
        return; // Don't play anything for silence
    }

    // Create and play the sound
    lullabySound.current = new Howl({
      src: [soundUrl],
      loop: true,
      volume: 0.5,
      autoplay: true
    });
  };

  // Format remaining time as MM:SS
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  // Navigate back to story screen
  const goToStoryScreen = () => {
    navigate('/');
  };

  // Update app settings when fade duration changes
  const handleFadeDurationChange = (value) => {
    setFadeDuration(value);

    // Update app settings
    if (updateSettings) {
      updateSettings({
        bedtimeFadeDuration: value
      });
    }
  };

  return (
    <BedtimeModeContainer>
      <BackgroundOverlay />
      <BackgroundImage />

      <Header>
        <BackButton onClick={goToStoryScreen}>←</BackButton>
        <HeaderTitle>Bedtime Mode</HeaderTitle>
      </Header>

      <MainContent>
        <MoonContainer>
          <MoonImage src="/images/moon.png" alt="Moon" />
          {isBedtimeEnabled && (
            <StarsAnimation>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
            </StarsAnimation>
          )}
        </MoonContainer>

        <SettingPanel>
          <ToggleContainer>
            <ToggleLabel>Bedtime Mode</ToggleLabel>
            <Switch>
              <input
                type="checkbox"
                checked={isBedtimeEnabled}
                onChange={toggleBedtimeMode}
              />
              <span></span>
            </Switch>
          </ToggleContainer>

          <SliderContainer>
            <SliderLabel>Fade Duration</SliderLabel>
            <SliderRow>
              <Slider
                type="range"
                min="5"
                max="30"
                step="5"
                value={fadeDuration}
                onChange={(e) => handleFadeDurationChange(parseInt(e.target.value))}
                disabled={isBedtimeEnabled}
              />
              <SliderValue>{fadeDuration} min</SliderValue>
            </SliderRow>
          </SliderContainer>

          {isBedtimeEnabled && (
            <TimerContainer>
              <TimerLabel>Time Remaining</TimerLabel>
              <TimerValue>{formatTime(remainingTime)}</TimerValue>
              <VolumeIndicator>
                Volume: {Math.round(volume * 100)}%
              </VolumeIndicator>
            </TimerContainer>
          )}
        </SettingPanel>

        <LullabyContainer>
          <LullabyTitle>After Story Ends</LullabyTitle>

          <LullabyOption 
            selected={selectedLullaby === 'lullaby'}
            onClick={() => setSelectedLullaby('lullaby')}
          >
            <LullabyIcon>🎵</LullabyIcon>
            <LullabyText>Lullaby</LullabyText>
          </LullabyOption>

          <LullabyOption 
            selected={selectedLullaby === 'white_noise'}
            onClick={() => setSelectedLullaby('white_noise')}
          >
            <LullabyIcon>🌊</LullabyIcon>
            <LullabyText>White Noise</LullabyText>
          </LullabyOption>

          <LullabyOption 
            selected={selectedLullaby === 'silence'}
            onClick={() => setSelectedLullaby('silence')}
          >
            <LullabyIcon>🔇</LullabyIcon>
            <LullabyText>Silence</LullabyText>
          </LullabyOption>
        </LullabyContainer>
      </MainContent>
    </BedtimeModeContainer>
  );
};

export default BedtimeMode;
